import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { appRoot } from "./projection.js";
import { sha256Digest } from "./hash.js";
import { decodeCursorOffset, type AdmissionLimits } from "./limits.js";

/**
 * Server-enforced persisted-operation safelist (SPECIFICATION 5.1). The registry (`operations/operations.json`) is
 * generated by `pnpm api:registry` from the reviewed catalog; each entry's id is `sha256:<hex>` of its normalized
 * document (the same normalization and hash as GraphQL Code Generator's persisted documents, so generated clients
 * send ids the server knows). The product profile executes only registry documents; APQ registration is disabled.
 */

export interface VariableSpec {
  /** GraphQL type as written in the document (e.g. `String!`, `Int`, `[PrivacyClass!]!`). */
  graphqlType: string;
  type: "String" | "Int" | "Boolean" | "List";
  required?: boolean;
  default?: unknown;
  min?: number;
  max?: number;
  maxLength?: number;
  pattern?: string;
  /** Value is a connection cursor issued by this API; its decoded offset is bounded by limits.maxOffset. */
  cursor?: boolean;
  /** Server-bound value (never accepted from a caller), e.g. `actor.visibility`. */
  bind?: "actor.visibility";
}

export interface RegisteredOperation {
  id: string;
  name: string;
  document: string;
  costClass: string;
  staticCost: number;
  depth: number;
  maxResponseBytes: number;
  fragments: string[];
  questions: string[];
  variables: Record<string, VariableSpec>;
}

export interface CostClass {
  description: string;
  maxEstimatedCost: number;
  latencyTargetP95Ms: number;
}

export interface OperationRegistry {
  format: "bks-operation-registry.v1";
  generatedBy: string;
  releaseCompatibility: {
    releaseId: string;
    schemaDigest: string;
    schemaReleaseDigest: string | null;
    productProjectionDigest: string;
    executableGraphqlDigest: string;
  };
  limits: AdmissionLimits;
  costClasses: Record<string, CostClass>;
  operations: RegisteredOperation[];
}

export interface LoadedRegistry {
  registry: OperationRegistry;
  operationRegistryDigest: string;
  byId: Map<string, RegisteredOperation>;
  path: string;
}

export function defaultRegistryPath(): string {
  return join(appRoot(), "operations", "operations.json");
}

export function loadRegistry(path: string = defaultRegistryPath()): LoadedRegistry {
  if (!existsSync(path)) throw new Error(`operation registry ${path} is missing; run pnpm api:registry`);
  const bytes = readFileSync(path);
  const registry = JSON.parse(bytes.toString("utf8")) as OperationRegistry;
  if (registry.format !== "bks-operation-registry.v1") throw new Error(`${path}: unsupported registry format ${String(registry.format)}`);
  const byId = new Map<string, RegisteredOperation>();
  for (const op of registry.operations) {
    // Tamper check: the id is the digest of the stored document.
    if (sha256Digest(op.document) !== op.id) throw new Error(`registry entry ${op.name} id ${op.id} does not match its document`);
    if (byId.has(op.id)) throw new Error(`registry has duplicate id ${op.id}`);
    byId.set(op.id, op);
  }
  return { registry, operationRegistryDigest: sha256Digest(bytes), byId, path };
}

export class RequestRejected extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "RequestRejected";
  }
}

export interface PersistedRequestBody {
  query?: unknown;
  documentId?: unknown;
  operationName?: unknown;
  variables?: unknown;
  extensions?: { persistedQuery?: { version?: unknown; sha256Hash?: unknown } } & Record<string, unknown>;
}

/** Finds the registry operation a request names; throws RequestRejected for anything not safelisted. */
export function resolvePersistedOperation(loaded: LoadedRegistry, body: PersistedRequestBody): RegisteredOperation {
  let id: string | null = null;
  if (typeof body.documentId === "string") id = body.documentId.startsWith("sha256:") ? body.documentId : `sha256:${body.documentId}`;
  const apq = body.extensions?.persistedQuery;
  if (!id && apq && typeof apq.sha256Hash === "string") id = `sha256:${apq.sha256Hash}`;
  if (id && !/^sha256:[0-9a-f]{64}$/.test(id)) throw new RequestRejected(400, "PERSISTED_QUERY_INVALID", "document id must be sha256:<64 hex>");
  if (typeof body.query === "string" && body.query.length > 0) {
    const textId = sha256Digest(body.query);
    if (id && id !== textId) throw new RequestRejected(400, "PERSISTED_QUERY_MISMATCH", "query text does not match the supplied document id");
    if (!loaded.byId.has(textId)) {
      throw new RequestRejected(400, "PERSISTED_QUERY_REQUIRED", "this deployment executes safelisted persisted operations only; send a registered documentId");
    }
    id = textId;
  }
  if (!id) throw new RequestRejected(400, "PERSISTED_QUERY_REQUIRED", "this deployment executes safelisted persisted operations only; send a registered documentId");
  const op = loaded.byId.get(id);
  if (!op) throw new RequestRejected(404, "PERSISTED_QUERY_NOT_FOUND", `operation ${id} is not in the safelist (registry ${loaded.operationRegistryDigest})`);
  if (typeof body.operationName === "string" && body.operationName !== op.name) {
    throw new RequestRejected(400, "OPERATION_NAME_MISMATCH", `operationName ${body.operationName} does not match registered operation ${op.name}`);
  }
  return op;
}

export interface ActorBinding {
  visibility: string[];
}

/**
 * Validates caller variables against the registry bounds, applies defaults and adds server-bound values.
 * Unknown variables, caller-supplied server-bound variables and out-of-bound values are rejected.
 */
export function bindVariables(op: RegisteredOperation, supplied: unknown, actor: ActorBinding, limits: Pick<AdmissionLimits, "maxOffset">): Record<string, unknown> {
  if (supplied !== undefined && supplied !== null && (typeof supplied !== "object" || Array.isArray(supplied))) {
    throw new RequestRejected(400, "VARIABLES_INVALID", "variables must be an object");
  }
  const input = (supplied ?? {}) as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(input)) {
    const spec = op.variables[key];
    if (!spec) throw new RequestRejected(400, "VARIABLES_INVALID", `unknown variable $${key} for ${op.name}`);
    if (spec.bind) throw new RequestRejected(400, "ACTOR_BINDING_REJECTED", `$${key} is bound by the server from the verified actor context and cannot be supplied`);
  }
  for (const [key, spec] of Object.entries(op.variables)) {
    if (spec.bind === "actor.visibility") {
      out[key] = [...actor.visibility];
      continue;
    }
    let value = input[key];
    if (value === undefined || value === null) {
      if (spec.default !== undefined) value = spec.default;
      else if (spec.required) throw new RequestRejected(400, "VARIABLES_INVALID", `$${key} is required for ${op.name}`);
      else continue;
    }
    switch (spec.type) {
      case "Int": {
        if (typeof value !== "number" || !Number.isInteger(value)) throw new RequestRejected(400, "VARIABLES_INVALID", `$${key} must be an integer`);
        if (spec.min !== undefined && value < spec.min) throw new RequestRejected(400, "VARIABLES_OUT_OF_BOUNDS", `$${key}=${value} is below ${spec.min}`);
        if (spec.max !== undefined && value > spec.max) throw new RequestRejected(400, "VARIABLES_OUT_OF_BOUNDS", `$${key}=${value} exceeds ${spec.max}`);
        break;
      }
      case "String": {
        if (typeof value !== "string") throw new RequestRejected(400, "VARIABLES_INVALID", `$${key} must be a string`);
        if (spec.maxLength !== undefined && value.length > spec.maxLength) throw new RequestRejected(400, "VARIABLES_OUT_OF_BOUNDS", `$${key} exceeds ${spec.maxLength} characters`);
        if (spec.pattern && !new RegExp(spec.pattern, "u").test(value)) throw new RequestRejected(400, "VARIABLES_INVALID", `$${key} has an invalid format`);
        if (spec.cursor) {
          const offset = decodeCursorOffset(value);
          if (offset === null) throw new RequestRejected(400, "CURSOR_INVALID", `$${key} is not a cursor issued by this API`);
          if (offset > limits.maxOffset) throw new RequestRejected(400, "OFFSET_EXCEEDED", `$${key} pages past offset ${limits.maxOffset}`);
        }
        break;
      }
      case "Boolean": {
        if (typeof value !== "boolean") throw new RequestRejected(400, "VARIABLES_INVALID", `$${key} must be a boolean`);
        break;
      }
      default:
        throw new RequestRejected(400, "VARIABLES_INVALID", `$${key} cannot be supplied`);
    }
    out[key] = value;
  }
  return out;
}
